#!/usr/bin/env python3
import argparse,datetime,hashlib,json
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);ap.add_argument('--commit',required=True);a=ap.parse_args();r=a.root;d=json.loads((r/'results/run_provenance_v80.json').read_text());d['schema']='run_provenance_v81';d['created_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();d['github_main_commit']=a.commit;d['source_alignment']='results/main_nersc_source_alignment_v40.json';d['source_alignment_sha256']=sha(r/'results/main_nersc_source_alignment_v40.json');d['stage_progress']='results/stage_progress_v25.json';d['stage_progress_sha256']=sha(r/'results/stage_progress_v25.json');d['stage8_holdout_report']='results/stage8_holdout_validation_report_v8.json';d['stage8_holdout_report_sha256']=sha(r/'results/stage8_holdout_validation_report_v8.json');d['b1_bphi_crosscovariance']='results/b1_bphi_crosscov_disjoint_audit_v1.json';d['b1_bphi_crosscovariance_sha256']=sha(r/'results/b1_bphi_crosscov_disjoint_audit_v1.json');d['batch_outputs']['source_alignment_v40']='results/main_nersc_source_alignment_v40.json';d['batch_outputs']['stage_progress_v25']='results/stage_progress_v25.json';d['batch_outputs']['stage8_holdout_report_v8']='results/stage8_holdout_validation_report_v8.json';d['batch_outputs']['b1_bphi_crosscovariance']='results/b1_bphi_crosscov_disjoint_audit_v1.json';d['status']='PARTIAL';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'status':d['status'],'commit':a.commit}))
